From fe6b0a08217c065d63880699e12ea5b070dae2ac Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:57:54 +0100
Subject: [PATCH] applets/devicenotifier: warn when a mounted device is
 unplugged

Unplugging a removable drive while it was still mounted went by without
any feedback, so users never learned that they could lose data. Now the
applet sends a notification asking them to safely remove devices first.

BUG: 396927
---
 applets/devicenotifier/devicenotifications.notifyrc |  6 ++++++
 applets/devicenotifier/messageinfo.cpp              | 11 +++++++++++
 applets/devicenotifier/stateinfo.cpp                |  7 +++++++
 applets/devicenotifier/stateinfo.h                  |  2 ++
 4 files changed, 26 insertions(+)

diff --git a/applets/devicenotifier/devicenotifications.notifyrc b/applets/devicenotifier/devicenotifications.notifyrc
index da435f5bd6..2c50d90a71 100644
--- a/applets/devicenotifier/devicenotifications.notifyrc
+++ b/applets/devicenotifier/devicenotifications.notifyrc
@@ -142,3 +142,9 @@ Name[zh_CN]=设备状态
 Name[zh_TW]=裝置狀態
 Sound=dialog-information
 Action=Sound
+
+[Event/unsafelyRemoved]
+Name=Device Not Safely Removed
+Comment=A device was unplugged without being safely removed first
+Sound=dialog-warning
+Action=Popup
diff --git a/applets/devicenotifier/messageinfo.cpp b/applets/devicenotifier/messageinfo.cpp
index e5c987879b..ccd9162b0c 100644
--- a/applets/devicenotifier/messageinfo.cpp
+++ b/applets/devicenotifier/messageinfo.cpp
@@ -86,6 +86,17 @@ void MessageInfo::onStateChanged()
     auto operationResult = m_stateInfo->getOperationResult();
     auto state = m_stateInfo->getState();

+    if (state == StateInfo::NotPresent && m_stateInfo->wasRemovedWhileMounted() && m_storageInfo->hasRemovableParent()) {
+        KNotification::event(QStringLiteral("unsafelyRemoved"),
+                             i18nc("@title:notification", "Device Not Safely Removed"),
+                             i18nc("@info:notification %1 is a device name",
+                                   "“%1” was unplugged without being safely removed first. To avoid losing data, safely remove devices before unplugging them.",
+                                   m_storageInfo->description()),
+                             u"device-notifier"_s,
+                             KNotification::CloseOnTimeout,
+                             u"devicenotifications"_s);
+    }
+
     // If the state is NotPresent, clear the old message to prevent it from being shown.
     if (operationResult == Solid::ErrorType::NoError && (state == StateInfo::MountDone || state == StateInfo::NotPresent)) {
         notify(QString());
diff --git a/applets/devicenotifier/stateinfo.cpp b/applets/devicenotifier/stateinfo.cpp
index a3e3060573..14fd4bc653 100644
--- a/applets/devicenotifier/stateinfo.cpp
+++ b/applets/devicenotifier/stateinfo.cpp
@@ -27,6 +27,7 @@ StateInfo::StateInfo(const std::shared_ptr<StorageInfo> &storageInfo, QObject *p
     , m_isMounted(false)
     , m_isChecked(false)
     , m_needRepair(false)
+    , m_wasRemovedWhileMounted(false)
     , m_operationInfo(Solid::NoError)
     , m_state(Idle)
     , m_deviceTimeStamp(QDateTime::currentDateTimeUtc())
@@ -124,6 +125,11 @@ bool StateInfo::isSafelyRemovable() const
     return false;
 }

+bool StateInfo::wasRemovedWhileMounted() const
+{
+    return m_wasRemovedWhileMounted;
+}
+
 QDateTime StateInfo::getDeviceTimeStamp() const
 {
     return m_deviceTimeStamp;
@@ -202,6 +208,7 @@ void StateInfo::setNotPresentState(const QString &udi)
     if (m_state != UnmountDone && m_state != Unmounting && m_storageInfo->device().udi() == udi) {
         qCDebug(APPLETS::DEVICENOTIFIER) << "State Info " << udi << " : state changed to NotPresent";
         m_isBusy = false;
+        m_wasRemovedWhileMounted = m_isMounted;
         m_isMounted = false;
         m_state = NotPresent;
         m_operationInfo = Solid::NoError;
diff --git a/applets/devicenotifier/stateinfo.h b/applets/devicenotifier/stateinfo.h
index eb7b89a309..7bda05ba7f 100644
--- a/applets/devicenotifier/stateinfo.h
+++ b/applets/devicenotifier/stateinfo.h
@@ -48,6 +48,7 @@ public:
     bool isChecked() const;
     bool needRepair() const;
     bool isSafelyRemovable() const;
+    bool wasRemovedWhileMounted() const;
     QDateTime getDeviceTimeStamp() const;

     /**
@@ -87,6 +88,7 @@ private:
     bool m_isMounted;
     bool m_isChecked;
     bool m_needRepair;
+    bool m_wasRemovedWhileMounted;
     Solid::ErrorType m_operationResult;
     QVariant m_operationInfo;
     State m_state;
-- 
2.53.0
